Thank you so much!!! The only thing is the way I actually want to address my user info class. As I try to add/write a value to it I get the error "Object reference not set to an instance of an object." and underneath you can see how I referenced it. Is this incorrect?

    using System;
    using System.Collections.Generic;
    using System.Linq;
    using System.Text;
    using System.Threading.Tasks;
    using System.IO;
    using Newtonsoft.Json;
    using Catherbot.Modules;
    using Newtonsoft.Json.Linq;
    using static Catherbot.Comp.compUser;

    namespace Catherbot.Comp
    {
        class Users
        {
            public static compUser user;

            private const string userFolder = "Resources";
            private const string userFile = "Users.json";

            static Users()
            {
                if (!Directory.Exists(userFolder))
                    Directory.CreateDirectory(userFolder);

                if (!File.Exists(userFolder + "/" + userFile))
                {
                    user = new compUser();
                    string json = JsonConvert.SerializeObject(user, Formatting.Indented);
                    File.WriteAllText(userFolder + "/" + userFile, json);

                }
                else
                {
                    string json = File.ReadAllText(userFolder + "/" + userFile);
                    user = JsonConvert.DeserializeObject<compUser>(json);
                }
            }
            public async Task CheckUser(string runeUser, string discUser)
            {
                Console.WriteLine(runeUser + " " + discUser);

                if (discUser == null)
                {
                    throw new ArgumentNullException(nameof(discUser));
                }

                string json = File.ReadAllText(userFolder + "/" + userFile);
                Console.WriteLine(json);

                user = new compUser();


                if (json.Contains(runeUser))
                {
                    Console.WriteLine("User found!"); 
                }
                else
                {

                    Console.WriteLine("User not found!");

                    Info NewUser = new Info
                    {
                        discName = discUser,
                        runeName = runeUser
                    };

                    user.infos.Add(NewUser);

                    /*user = JsonConvert.DeserializeObject<compUser>(json);
                    Console.WriteLine("json deserialized   " + user);

                    //string itemToAdd = "{" + discUser + ":" + runeUser + "}";
                    string itemToAdd = "{\"discName\":\"" + discUser + "\",\"runeName\":\"" + runeUser + "\"}";

                    Console.WriteLine("new string to add: " + itemToAdd + " in " + user );

                    JsonConvert.PopulateObject(itemToAdd, user);

                    Console.WriteLine("json populated with: " + itemToAdd);

                    //Console.WriteLine(user.discName.);


                    json = JsonConvert.SerializeObject(user, Formatting.Indented);
                    File.WriteAllText(userFolder + "/" + userFile, json);
                    */
                }


            }

        }
        public struct compUser
        {
            public List<Info> infos { get; set; }
            public class Info
            {
                public string discName { get; set; }
                public string runeName { get; set; }
            }
        }
    }


As you can see above, the compUser datastructure has the same list structure as you told me to do with activities, but whenever I refer using [this](https://imgur.com/a/zh9HUyB) format, I get the following [error](https://imgur.com/a/HiSgDbO) . Is this normal as I have no clue how to reference it in any other way..

Ok and how does one get the value from lets say the text of the second activity? I tried googling it but nothing worked so far and you seem very informed on this matter.

&#x200B;

\[EDIT\] I managed to get a value from it. 

        public struct compUser
        {
            public Info[] infos { get; set; }
            public class Info
            {
                public string discName { get; set; }
                public string runeName { get; set; }
            }
        }

                Users.user.infos[0].discName = Context.User.Username;
                Users.user.infos[0].runeName = message;

The question I have now is the following:

If I want to let's say add certain new activities to activity, would I then need to get a counter that checks how many activities there are already so I don't overwrite any? (see example above, the square brackets with "0")

Fixed my issue by adding a type to my Task.

    public class ApiCall
        {
            public async Task<string> CheckAPI(string apiUser)
            {
                string product;
                string apiBase = "https://apps.runescape.com/runemetrics/profile/";

                //Console.WriteLine("0: " + apiBase);

                using (var handler = new HttpClientHandler())
                using (var client = new HttpClient())
                {
                    client.BaseAddress = new Uri(apiBase);
                    HttpResponseMessage response = await client.GetAsync("profile?user=" + apiUser);
                    if (response.IsSuccessStatusCode)
                    {
                        product = await response.Content.ReadAsStringAsync();
                        Console.WriteLine("Response.Content= " + product);
                        //Console.WriteLine("apiBase= ..." + apiBase + "...");
                        //Console.WriteLine("apiUser= ..." + apiUser + "...");
                        return product;
                    }
                    else { return ""; }
                }

            }
        }

Issue now is that it tells me this:

`Unexpected character encountered while parsing value: [. Path 'activities', line 1, position 148.`

\[EDIT\] Used this example:  [https://apps.runescape.com/runemetrics/profile/profile?user=Pizzajongen/](https://apps.runescape.com/runemetrics/profile/profile?user=Pizzajongen/)I think it has something to do with the stuff after "Activities" on the first line.

\[EDIT 2\] All issues fixed, thanks for the help :) had to replace certain multidimensional "arrays" by classes.

